import React, { useState } from 'react';
import { FaFilePdf, FaDownload, FaCalendarAlt } from 'react-icons/fa';
import './InterestRate.css';

const InterestRate = () => {
    // Current Active Rates (Based on typical Laghubitta rates)
    const currentRates = {
        effectiveDate: "2080/04/07",
        savings: [
            { name: "Group Saving", rate: "7.5%" },
            { name: "Personal Saving", rate: "7.5%" },
            { name: "Pension/Child Saving", rate: "9.0%" },
        ],
        loans: [
            { name: "General Loan", rate: "15.0%" },
            { name: "Micro-Enterprise Loan", rate: "15.0%" }
        ]
    };

    // Year-wise PDF Archive
    const pdfArchive = [
        { year: "2082/83", months: ["Chaitra", "Falgun", "Magh", "Poush", "Mangsir"] },
        { year: "2081/82", months: ["Full Year Archive"] },
        { year: "2080/81", months: ["Full Year Archive"] },
    ];

    const [selectedYear, setSelectedYear] = useState(pdfArchive[0].year);

    return (
        <div className="interest-page">
            <div className="interest-hero">
                <h1>Rates & Charges</h1>
                <p>Transparency in our financial services</p>
            </div>

            <div className="interest-content">
                {/* Left Side: PDF Archive (Reference to NDBL Style) */}
                <aside className="archive-sidebar">
                    <h3><FaCalendarAlt /> Archive by Year</h3>
                    <ul>
                        {pdfArchive.map((item) => (
                            <li 
                                key={item.year} 
                                className={selectedYear === item.year ? 'active' : ''}
                                onClick={() => setSelectedYear(item.year)}
                            >
                                F.Y. {item.year}
                            </li>
                        ))}
                    </ul>
                </aside>

                {/* Right Side: Details and Download Buttons */}
                <main className="details-main">
                    <div className="current-summary">
                        <h2>Interest Rates (Effective: {currentRates.effectiveDate})</h2>
                        <div className="rate-brief-grid">
                            <div className="brief-box">
                                <span>Savings (Up to)</span>
                                <h4>9.0%</h4>
                            </div>
                            <div className="brief-box">
                                <span>Loans (Max)</span>
                                <h4>15.0%</h4>
                            </div>
                        </div>
                    </div>

                    <h3>Download Official Notices for {selectedYear}</h3>
                    <div className="pdf-list">
                        {pdfArchive.find(a => a.year === selectedYear).months.map((month, index) => (
                            <div key={index} className="pdf-card">
                                <div className="pdf-info">
                                    <FaFilePdf className="pdf-icon-red" />
                                    <span>Interest Rate Notice - {month}</span>
                                </div>
                                <a 
                                    href={`/assets/pdf/interest/rate-${selectedYear.replace('/','-')}-${month.toLowerCase()}.pdf`} 
                                    className="btn-download"
                                    target="_blank" 
                                    rel="noreferrer"
                                >
                                    <FaDownload /> Download
                                </a>
                            </div>
                        ))}
                    </div>
                </main>
            </div>
        </div>
    );
};

export default InterestRate;
